class Solution:
    def minimizeSum(self, nums: List[int]) -> int:
        vals = sorted(set(nums))
        total = 0
        for x in nums:
            best = x
            for v in vals:
                if v >= best:
                    break
                if x % v == 0:
                    best = v
                    break
            total += best
        return total

