class Solution {
public:
    long long minimizeSum(vector<int>& nums) {
        vector<int> vals = nums;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        long long total = 0;
        for (int x : nums) {
            long long best = x;
            for (int v : vals) {
                if (v >= best) break;
                if (x % v == 0) { best = v; break; }
            }
            total += best;
        }
        return total;
    }
};

