class Solution:
    def minimizeSum(self, nums: List[int]) -> int:
        V = max(nums)
        best = list(range(V + 1))
        for s in set(nums):
            for m in range(s, V + 1, s):
                if s < best[m]:
                    best[m] = s
        return sum(min(x, best[x]) for x in nums)

