class Solution {
public:
    long long minimizeSum(vector<int>& nums) {
        int V = *max_element(nums.begin(), nums.end());
        vector<int> best(V + 1);
        iota(best.begin(), best.end(), 0);
        for (int s : unordered_set<int>(nums.begin(), nums.end()))
            for (long long m = s; m <= V; m += s)
                best[m] = min(best[m], s);
        long long total = 0;
        for (int x : nums) total += min(x, best[x]);
        return total;
    }
};

