class Solution {
    public long minimizeSum(int[] nums) {
        int V = 0;
        for (int x : nums) V = Math.max(V, x);
        int[] best = new int[V + 1];
        for (int i = 0; i <= V; i++) best[i] = i;
        HashSet<Integer> set = new HashSet<>();
        for (int x : nums) set.add(x);
        for (int s : set)
            for (int m = s; m <= V; m += s)
                if (s < best[m]) best[m] = s;
        long total = 0;
        for (int x : nums) total += Math.min(x, best[x]);
        return total;
    }
}

